            4'd8: rbs = {(keys[56] & keys[61]), ((keys[55] & ~(keys[15] | keys[52])) | (keys[55] & (keys[15] | keys[52]))), 1'b0, keys[51], keys[36], keys[60], keys[23], keys[5]};
            4'd9: rbs = {1'b0, 1'b0, ((keys[49] & ~(keys[15] | keys[52])) | (keys[49] & (keys[15] | keys[52])) | (keys[45] & ~(keys[15] | keys[52]))), keys[63], ((keys[32] & ~(keys[15] | keys[52]) & ~keys[61]) | (keys[32] & (keys[15] | keys[52]) & ~keys[61])), ((keys[19] & ~(keys[15] | keys[52]) & ~keys[61]) | (keys[19] & (keys[15] | keys[52]) & ~keys[61])), ((keys[8] & ~(keys[15] | keys[52]) & ~keys[61]) | (keys[8] & (keys[15] | keys[52]) & ~keys[61])), keys[57]};
